using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class RudyardKipling
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Words are, of course, the most powerful drug used by mankind.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "There is no middle way in this war. We do not doubt our ultimate victory any more than we doubt the justice of our cause.It is not conceivable that we should fail, for if we fail the lights of freedom go out over the whole world.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "The individual has always had to struggle to keep from being overwhelmed by the tribe. To be your own man is a hard business. If you try it, you'll be lonely often, and sometimes frightened. But no price is too high to pay for the privilege of owning yourself.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "I have eaten your bread and salt. I have drunk your water and wine. The deaths ye died I have watched beside And the lives ye led were mine.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "I have written the tale of our life For a sheltered people's mirth, In jesting guise-but ye are wise, And ye know what the jest is worth.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "A fool there was and he made his prayer (Even as you and I!) To a rag and a bone and a hank of hair We called her the woman who did not care), But the fool he called her his lady fair (Even as you and I!)", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Call a truce, then, to our labours let us feast with friends and neighbours, And be merry as the custom of our caste; For if \"faint and forced the laughter,\" and if sadness follow after, We are richer by one mocking Christmas past.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "The toad beneath the harrow knows Exactly where each tooth point goes; The butterfly upon the road Preaches contentment to that toad.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "And a woman is only a woman, but a good cigar is a smoke.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "God of our fathers, known of old, Lord of our far-flung battle line, Beneath whose awful hand we hold Dominion over palm and pine- Lord God of Hosts, be with us yet, Lest we forget-lest we forget!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "The tumult and the shouting dies; The Captains and the Kings depart; Still stands Thine ancient sacrifice, An humble and a contrite heart. Lord God of Hosts, be with us yet, Lest we forget-lest we forget!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If, drunk with sight of power, we loose Wild tongues that have not Thee in awe, Such boastings as the Gentiles use, Or lesser breeds without the Law - Lord God of Hosts, be with us yet, Lest we forget-lest we forget!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "It takes a great deal of Christianity to wipe out uncivilized Eastern instincts, such as falling in love at first sight.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "The silliest woman can manage a clever man; but it needs a very clever woman to manage a fool!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Never praise a sister to a sister, in the hope of your compliments reaching the proper ears, and so preparing the way for you later on. Sisters are women first, and sisters afterwards; and you will find that you do yourself harm.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Everyone is more or less mad on one point.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "East of Suez, some hold, the direct control of Providence ceases; Man being there handed over to the power of the Gods and Devils of Asia, and the Church of England Providence only exercising an occasional and modified supervision in the case of Englishmen.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "And oft-times cometh our wise Lord God, master of every trade, And tells them tales of His daily toil, of Edens newly made; And they rise to their feet as He passes by, gentlemen unafraid.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "I've taken my fun where I've found it; I've rogued an' I've ranged in my time.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "For the colonel's lady an' Judy O'Grady, Are sisters under their skins.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "We aren't no thin red 'eroes, nor we aren't no blackguards too, But single men in barricks, most remarkable like you; An' if sometimes our conduck isn't all your fancy paints, Why, single men in barricks don't grow into plaster saints.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "For it's Tommy this, an' Tommy that, an' \"Chuck him out, the brute!\" But it's \"Saviour of 'is country\" when the guns begin to shoot.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "So 'ere's to you, Fuzzy-Wuzzy, at your 'ome in the Soudan; You're a pore benighted 'eathen but a first-class fightin' man.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "'E's all 'ot sand an' ginger when alive An' 'e's generally shammin' when 'e's dead.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "You may talk o' gin and beer When you're quartered safe out 'ere, An' you're sent to penny-fights an' Aldershot it; But when it comes to slaughter You will do your work on water, An' you'll lick the bloomin' boots of 'im that's got it.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If your officer's dead and the sergeants look white, Remember it's ruin to run from a fight: So take open order, lie down, and sit tight, And wait for supports like a soldier.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "When you're wounded and left on Afghanistan's plains, And the women come out to cut up what remains, Jest roll to your rifle and blow out your brains An' go to your Gawd like a soldier.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Oh the road to Mandalay Where the flyin'-fishes play An' the dawn comes up like thunder outer China 'crost the Bay!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "By the old Moulmein Pagoda, lookin' eastward to the sea, There's a Burma girl a-settin', and I know she thinks o' me; For the wind is in the palm-trees, and the temple-bells they say: \"Come you back, you British soldier; come you back to Mandalay!\"", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Ship me somewheres east of Suez, where the best is like the worst, Where there aren't no Ten Commandments, an' a man can raise a thirst.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "We have done with Hope and Honour, we are lost to Love and Truth, We are dropping down the ladder rung by rung, And the measure of our torment is the measure of our youth. God help us, for we knew the worst too young!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "There is none like to me!' says the Cub in the pride of his earliest kill; But the jungle is large and the Cub he is small. Let him think and be still.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "We be of one blood, ye and I.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Brother, thy tail hangs down behind! This is the way of the Monkey-kind!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Now this is the Law of the Jungle-as old and as true as the sky; And the Wolf that shall keep it may prosper, but the Wolf that shall break it must die.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "For the strength of the Pack is the Wolf, and the strength of the Wolf is the Pack.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "When Pack meets with Pack in the Jungle, and neither will go from the trail, Lie down till the leaders have spoken-it may be fair words shall prevail.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Now these are the Laws of the jungle, and many and mighty are they; But the head and the hoof of the Law and the haunch and the hump is-Obey!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can keep your head when all about you Are losing theirs and blaming it on you, If you can trust yourself when all men doubt you, But make allowance for their doubting too;", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can wait and not be tired by waiting, Or being lied about, don't deal in lies, Or being hated, don't give way to hating, And yet don't look too good, nor talk too wise", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can dream-and not make dreams your master; If you can think-and not make thoughts your aim; If you can meet with Triumph and Disaster And treat those two imposters just the same", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can bear to hear the truth you've spoken Twisted by knaves to make a trap for fools, Or watch the things you gave your life to, broken, And stoop and build 'em up with worn-out tools", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can make one heap of all your winnings And risk it on one turn of pitch-and-toss, And lose, and start again at your beginnings And never breathe a word about your loss", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can force your heart and nerve and sinew To serve your turn long after they are gone, And so hold on when there is nothing in you Except the will which says to them: \"Hold on!\"", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can talk with crowds and keep your virtue, Or walk with kings-nor lose the common touch, If neither foes nor loving friends can hurt you, If all men count with you, but none too much;", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If you can fill the unforgiving minute With sixty seconds' worth of distance run, Yours is the Earth and everything that's in it, And-which is more-you'll be a Man, my son!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "We have fed our sea for a thousand years And she calls us, still unfed, Though there's never a wave of all her waves But marks our English dead.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "They change their skies above them, But not their hearts that roam!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "There's a Legion that never was 'listed, That carries no colours or crest, But, split in a thousand detachments, Is breaking the road for the rest.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "There are nine and sixty ways of constructing tribal lays, And every single one of them is right!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "For 'im that doth not work must surely die; But that's no reason man should labour all 'Is life on one same shift-life's none so long.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "It's like a book, I think, this bloomin' world, Which you can read and care for just so long, But presently you feel that you will die Unless you get the page you're readin' done, An' turn another-likely not so good; But what you're after is to turn 'em all.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "'E's a sort of a bloomin' cosmopolouse-soldier an' sailor too.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "When Earth's last picture is painted and the tubes are twisted and dried, When the oldest colours have faded, and the youngest critic has died, We shall rest, and, faith, we shall need it-lie down for an aeon or two, Till the Master of All Good Workmen shall put us to work anew!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "And only the Master shall praise us, and only the Master shall blame; And no one shall work for money, and no one shall work for fame, But each for the joy of the working, and each, in his separate star, Shall draw the Thing as he sees It for the God of Things as They Are!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Take up the White Man's burden-- Send forth the best ye breed-- Go bind your sons to exile, To serve your captives' need; To wait in heavy harness, On fluttered folk and wild-- Your new-caught, sullen peoples, Half-devil and half-child.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Take up the White Man's burden-- In patience to abide, To veil the threat of terror, And check the show of pride; By open speech and simple, An hundred times made plain To seek another's profit, And work another's gain.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "I keep six honest serving-men: (They taught me all I knew) Their names are What and Where and When And How and Why and Who.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Ye know who use the Crystal Ball (To peer by stealth on Doom), The Shade that, shaping first of all, Prepares an empty room. Then doth It pass Like breath from glass, But, on the extorted vision bowed intent, No man considers why It came or went.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Cities and Thrones and Powers, Stand in Time's eye, Almost as long as flowers, Which daily die: But, as new buds put forth To glad new men, Out of the spent and unconsidered Earth, The Cities rise again.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Of all the trees that grow so fair, Old England to adorn, Greater are none beneath the Sun, Than Oak, and Ash, and Thorn.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Take of English earth as much As either hand may rightly clutch. In the taking of it breathe Prayer for all who lie beneath.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "If any question why we died, Tell them, because our fathers lied.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Body and spirit I surrendered whole To harsh instructors-and received a soul... If mortal man could change me through and through From all I was-What may the God not do?", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "From little towns in a far land we came, To save our honour and a world aflame. By little towns in a far land we sleep, And trust the world we won for you to keep.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "I could not dig: I dared not rob: Therefore I lied to please the mob. Now all my lies are proved untrue And I must face the men I slew. What tale shall serve me here among Mine angry and defrauded young?", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "But that's another story.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Being kissed by a man who didn't wax his moustache was like eating an egg without salt.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Men and women may sometimes, after great effort, achieve a creditable lie; but the house, which is their temple, cannot say anything save the truth of those who have lived in it.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Enough work to do, and strength enough to do the work.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Brothers and Sisters, I bid you beware Of giving your heart to a dog to tear.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "For the female of the species is more deadly than the male.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "For all we have and are, For all our children's fate, Stand up and take the war. The Hun is at the gate!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "No easy hope or lies Shall bring us to our goal, But iron sacrifice Of body, will, and soul.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "There is but one task for all- One life for each to give. What stands if Freedom fall? Who dies if England live?", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "As I pass through my incarnations in every age and race, I make my proper prostrations to the Gods of the Market-Place. Peering through reverent fingers I watch them flourish and fall, And the Gods of the Copybook Headings, I notice, outlast them all.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Never again will I spend another winter in this accursed bucket shop of a refrigerator called England.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "A people always ends by resembling its shadow.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "When your Daemon is in charge, do not try to think consciously. Drift, wait, and obey.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Four things greater than all things are,- Women and Horses and Power and War.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Two things greater than all things are, The first is Love, and the second War.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "There be triple ways to take, of the eagle or the snake, Or the way of a man with a maid\"; But the fairest way to me is a ship's upon the sea In the heel of the North-East Trade.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Oh, Adam was a gardener, and God who made him sees That half a proper gardener's work is done upon his knees, So when your work is finished, you can wash your hands and pray For the Glory of the Garden that it may not pass away!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Father, Mother, and Me, Sister and Auntie say All the people like us are We, And every one else is They.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "We are not built to comprehend a lie, We can neither love nor pity nor forgive, If you make a slip in handling us you die! We are greater than the Peoples or the Kings- Be humble, as you crawl beneath our rods!- Our touch can alter all created things, We are everything on earth-except The Gods!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Though our smoke may hide the Heavens from your eyes, It will vanish and the stars will shine again, Because, for all our power and weight and size, We are nothing more than children of your brain!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Down to Gehenna or up to the Throne, He travels the fastest who travels alone.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "More men are killed by overwork than the importance of the world justifies.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Oh, East is East, and West is West, and never the twain shall meet, Till Earth and Sky stand presently at God's great Judgment Seat; But there is neither East nor West, border, nor breed, nor birth, When two strong men stand face to face, though they come from the ends of the earth!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "For all we take we must pay, but the price is cruel high.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "When the flush of a new-born sun fell first on Eden's green and gold, Our father Adam sat under the Tree and scratched with a stick in the mould; And the first rude sketch that the world had seen was joy to his mighty heart, Till the Devil whispered behind the leaves, \"It's pretty, but is it Art?\"", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "We know that the tail must wag the dog, for the horse is drawn by the cart; But the Devil whoops, as he whooped of old: \"It's clever, but is it Art?\"", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Bite on the bullet, old man, and don't let them think you're afraid.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "San Francisco is a mad city-inhabited for the most part by perfectly insane people, whose women are of a remarkable beauty.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Asia is not going to be civilised after the methods of the West. There is too much Asia and she is too old.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Winds of the World, give answer! They are whimpering to and fro- And what should they know of England who only England know?", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Ever the wide world over, lass, Ever the trail held true, Over the world and under the world, And back at the last to you.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "When 'Omer smote 'is bloomin' lyre, He'd 'eard men sing by land an' sea; An' what he thought 'e might require, 'E went an' took-the same as me!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Take up the White Man's burden- Send forth the best ye breed- Go bind your sons to exile To serve your captives' need.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Let us admit it fairly, as a business people should, We have had no end of a lesson: it will do us no end of good.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "It was our fault, and our very great fault-and now we must turn it to use. We have forty million reasons for failure, but not a single excuse.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Men, not children or servants, tempered and taught to the end; Cleansed of servile panic, slow to dread or despise, Humble because of knowledge, mighty by sacrifice.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "God gave all men all earth to love, But since our hearts are small, Ordained for each one spot should prove Belovèd over all.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Who hath desired the Sea?-the sight of salt water unbounded- The heave and the halt and the hurl and the crash of the comber wind-hounded?", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Something hidden. Go and find it. Go and look behind the Ranges- Something lost behind the Ranges. Lost and waiting for you. Go!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Boots-boots-boots-boots-movin' up and down again! There's no discharge in the war!", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "That's the secret. 'Tisn't beauty, so to speak, nor good talk necessarily. It's just It. Some women'll stay in a man's memory if they once walk down a street.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "... scandals are only increased by hushing them up.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "... it's always best to tell the truth.", Author = "Rudyard Kipling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Rudyard_Kipling", Text = "Fiction is Truth's elder sister. Obviously. No one in the world knew what truth was till some one had told a story.", Author = "Rudyard Kipling" },
        };
    }
}